{
  "meta": {
    "name": "Warehouse Inventory Manager",
    "description": "An inventory management system for a warehouse to track products, suppliers, and stock levels, with features for staff to record stock movements and admins to manage suppliers and view low-stock reports."
  },
  "entities": [
    {
      "name": "Product",
      "fields": [
        {
          "name": "name",
          "type": "string",
          "required": true
        },
        {
          "name": "sku",
          "type": "string",
          "required": true,
          "unique": true
        },
        {
          "name": "description",
          "type": "text"
        },
        {
          "name": "quantity",
          "type": "integer",
          "required": true,
          "default": 0
        },
        {
          "name": "reorderPoint",
          "type": "integer",
          "required": true,
          "default": 0
        }
      ]
    },
    {
      "name": "Supplier",
      "fields": [
        {
          "name": "name",
          "type": "string",
          "required": true
        },
        {
          "name": "contactInfo",
          "type": "string"
        },
        {
          "name": "address",
          "type": "text"
        }
      ]
    },
    {
      "name": "StockMovement",
      "fields": [
        {
          "name": "quantityChange",
          "type": "integer",
          "required": true
        },
        {
          "name": "movementType",
          "type": "enum",
          "required": true,
          "enumValues": [
            "received",
            "shipped",
            "adjusted"
          ]
        },
        {
          "name": "timestamp",
          "type": "datetime",
          "required": true,
          "default": "now()"
        }
      ],
      "relations": [
        {
          "name": "product",
          "kind": "manyToOne",
          "target": "Product",
          "required": true
        }
      ]
    }
  ],
  "roles": [
    {
      "name": "admin",
      "description": "Manages suppliers and views reports."
    },
    {
      "name": "staff",
      "description": "Records stock movements.",
      "isDefault": true
    }
  ],
  "permissions": [
    {
      "role": "staff",
      "entity": "Product",
      "actions": [
        "read"
      ]
    },
    {
      "role": "staff",
      "entity": "StockMovement",
      "actions": [
        "create",
        "read"
      ]
    },
    {
      "role": "admin",
      "entity": "Product",
      "actions": [
        "create",
        "read",
        "update",
        "delete"
      ]
    },
    {
      "role": "admin",
      "entity": "Supplier",
      "actions": [
        "create",
        "read",
        "update",
        "delete"
      ]
    },
    {
      "role": "admin",
      "entity": "StockMovement",
      "actions": [
        "read"
      ]
    }
  ],
  "pages": [
    {
      "name": "Products",
      "route": "/products",
      "type": "list",
      "entity": "Product",
      "access": [
        "admin",
        "staff"
      ],
      "fields": [
        "name",
        "sku",
        "quantity",
        "reorderPoint"
      ]
    },
    {
      "name": "Product Detail",
      "route": "/products/:id",
      "type": "detail",
      "entity": "Product",
      "access": [
        "admin",
        "staff"
      ]
    },
    {
      "name": "New Product",
      "route": "/products/new",
      "type": "form",
      "entity": "Product",
      "access": [
        "admin"
      ]
    },
    {
      "name": "Edit Product",
      "route": "/products/:id/edit",
      "type": "form",
      "entity": "Product",
      "access": [
        "admin"
      ]
    },
    {
      "name": "Suppliers",
      "route": "/suppliers",
      "type": "list",
      "entity": "Supplier",
      "access": [
        "admin"
      ],
      "fields": [
        "name",
        "contactInfo"
      ]
    },
    {
      "name": "New Supplier",
      "route": "/suppliers/new",
      "type": "form",
      "entity": "Supplier",
      "access": [
        "admin"
      ]
    },
    {
      "name": "Edit Supplier",
      "route": "/suppliers/:id/edit",
      "type": "form",
      "entity": "Supplier",
      "access": [
        "admin"
      ]
    },
    {
      "name": "Stock Movements",
      "route": "/stock-movements",
      "type": "list",
      "entity": "StockMovement",
      "access": [
        "admin",
        "staff"
      ],
      "fields": [
        "product.name",
        "quantityChange",
        "movementType",
        "timestamp"
      ]
    },
    {
      "name": "Log Stock Movement",
      "route": "/stock-movements/new",
      "type": "form",
      "entity": "StockMovement",
      "access": [
        "staff"
      ]
    },
    {
      "name": "Low Stock Report",
      "route": "/reports/low-stock",
      "type": "list",
      "entity": "Product",
      "access": [
        "admin"
      ],
      "fields": [
        "name",
        "sku",
        "quantity",
        "reorderPoint"
      ],
      "filters": [
        {
          "field": "quantity",
          "operator": "<=",
          "valueField": "reorderPoint"
        }
      ]
    }
  ],
  "businessRules": [
    {
      "type": "ownership",
      "id": "productOwnership",
      "entity": "Product"
    },
    {
      "type": "ownership",
      "id": "supplierOwnership",
      "entity": "Supplier"
    },
    {
      "type": "ownership",
      "id": "stockMovementOwnership",
      "entity": "StockMovement"
    }
  ],
  "auth": {
    "strategy": "email_password",
    "requireAuth": true
  }
}
